/// The number of samplers defined in the shader.
samplers: u32,
/// The number of readonly storage textures defined in the shader.
readonly_storage_textures: u32,
/// The number of readonly storage buffers defined in the shader.
readonly_storage_buffers: u32,
/// The number of read-write storage textures defined in the shader.
readwrite_storage_textures: u32,
/// The number of read-write storage buffers defined in the shader.
readwrite_storage_buffers: u32,
/// The number of uniform buffers defined in the shader.
uniform_buffers: u32,
/// The number of threads in the X dimension.
threadcount_x: u32,
/// The number of threads in the Y dimension.
threadcount_y: u32,
/// The number of threads in the Z dimension.
threadcount_z: u32,
